'use strict';
const feedCache={},feedBusy=new Set(),lastAttempt={};let historyBusy=false;
const pct=v=>v===null||!Number.isFinite(v)?'—':(v*100).toFixed(5)+'%';
function age(t){if(!t)return 'Time unavailable';const sec=Math.floor((Date.now()-t)/1000);if(sec< -30)return 'Timestamp in future';if(sec<60)return Math.max(0,sec)+'s';if(sec<3600)return Math.floor(sec/60)+'m';return Math.floor(sec/3600)+'h';}
function fundingText(r){if(r.type==='swap')return `L ${pct(r.fundingLong)} / S ${pct(r.fundingShort)} (${r.fundingStage} payment)`;return pct(r.funding)+(r.fundingSeconds?' / '+fmt(r.fundingSeconds/3600,1)+'h':' / reported interval');}
function visibleMarkets(){return (feedCache[venue]?.rows||[]).filter(r=>!$('tradfi-only').checked||r.tradfi).sort((a,b)=>a.symbol.localeCompare(b.symbol));}
function updateLiveNotice(){if(page!=='live')return;$('source-pill').textContent='● Public exchange data';$('notice').textContent='Current snapshots and completed historical candles are separate. Quote age matters; cached prices, closed sessions and oracle candles are not executable trade quotes.';$('notice').classList.add('live-notice');}
const oldShow=show;show=function(p){oldShow(p);$('notice').classList.toggle('live-notice',p==='live');if(p==='live')updateLiveNotice();else render();};
function renderFeed(){const cache=feedCache[venue],rows=visibleMarkets();$('feed-description').textContent=venue==='Popdex'?'Public web feed via the local relay. These website endpoints may change without notice.':venue==='Arcus'?'Official public API. Historical OHLC prices come from the oracle, not executed trades.':'Official v2 public API. Perpetual and swap contracts retain their exact identifiers; historical candles are not available through this feed.';
$('refresh-feed').disabled=feedBusy.has(venue);$('refresh-feed').textContent=feedBusy.has(venue)?'Connecting…':'Refresh prices';
$('feed-status').className=cache?.error?'feed-bad':'feed-good';$('feed-status').textContent=cache?`${cache.error?'Refresh failed: '+cache.error+'. Showing last successful data. ':''}${cache.rows.length} listed markets · fetched ${date(cache.fetched)} UTC (${age(cache.fetched)} ago)${cache.total!==null&&cache.coverage<cache.total?` · partial prices: ${cache.coverage}/${cache.total}`:''}`:'No snapshot loaded for '+venue+'. Select Refresh prices.';
const q=$('market-search').value.toLowerCase();$('live-markets').innerHTML=rows.filter(r=>(r.symbol+' '+r.name).toLowerCase().includes(q)).map(r=>`<tr><td><span class="pair-title">${esc(r.symbol)}</span><span class="pair-sub">${esc(r.name)} · ${esc(r.type)}</span></td><td class="number">${r.price===null?'—':fmt(r.price,r.price<1?6:2)}</td><td>${r.volume===null?'—':money(r.volume)}</td><td>${fmt(r.spread)}</td><td>${esc(fundingText(r))}</td><td>${r.quoteTime?age(r.quoteTime):'Source time unavailable'}${r.quoteTime&&Date.now()-r.quoteTime>120000?' · stale':''}<span class="pair-sub">${esc(r.status)}${r.offHours?' · outside regular hours':''}${r.session?' · '+esc(r.session):''}</span></td></tr>`).join('')||'<tr><td colspan="6">No matching markets. Refresh or change the filter.</td></tr>';
for(const id of ['live-a','live-b']){const previous=$(id).value;$(id).innerHTML=rows.map(r=>`<option value="${esc(r.id)}">${esc(r.symbol)} · ${esc(r.name)} · ${esc(r.type)}</option>`).join('');if(rows.some(r=>r.id===previous))$(id).value=previous;}
if($('live-a').value===$('live-b').value&&rows.length>1)$('live-b').selectedIndex=1;
renderLivePair();updateLiveNotice();}
function renderLivePair(){const rows=feedCache[venue]?.rows||[],a=rows.find(r=>r.id===$('live-a').value),b=rows.find(r=>r.id===$('live-b').value);$('load-history').disabled=historyBusy||!a||!b||a.id===b.id||venue==='Variational';$('load-history').textContent=historyBusy?'Loading candles…':venue==='Variational'?'Historical candles unavailable':'Load completed 5m candles →';
$('live-pair-details').innerHTML=a&&b?`<strong>${esc(a.symbol)} / ${esc(b.symbol)} · ${esc(venue)}</strong><br>A: bid ${fmt(a.bid)} / ask ${fmt(a.ask)} · funding ${esc(fundingText(a))}<br>B: bid ${fmt(b.bid)} / ask ${fmt(b.ask)} · funding ${esc(fundingText(b))}<br>${venue==='Variational'?'Funding is per stated payment interval. Swap long rate means longs pay; short rate means shorts receive. Quotes may be cached for up to 10 minutes.': 'Funding is shown exactly as a reported decimal rate; its interval is not yet verified here, so no annualized comparison is calculated.'}<br>${venue==='Arcus'?'History: up to 1,500 five-minute oracle bars per leg. May include flat, zero-volume buckets.':venue==='Popdex'?'History: up to 1,000 five-minute market candles per leg. The current incomplete bar is removed.':'Use imported historical prices for research; snapshots are never presented as candle history.'}${a.type!==b.type?'<br><strong>Different contract types selected. Funding and settlement are not equivalent.</strong>':''}`:'Connect this venue to select both legs.';}
async function refreshFeed(){const target=venue;if(feedBusy.has(target))return;if(Date.now()-(lastAttempt[target]||0)<30000){toast('Wait 30 seconds between snapshot requests.');return;}lastAttempt[target]=Date.now();feedBusy.add(target);renderFeed();try{feedCache[target]=await MarketFeeds.markets(target);if(venue===target){renderFeed();if(!$('live-a').value.includes('NVDA')){const rows=visibleMarkets(),a=rows.find(r=>r.symbol.startsWith('NVDA')),b=rows.find(r=>r.symbol.startsWith('AMD'))||rows.find(r=>r.symbol.startsWith('MU'));if(a&&b){$('live-a').value=a.id;$('live-b').value=b.id;renderLivePair();}}}}catch(err){if(feedCache[target])feedCache[target].error=err.message;if(venue===target){$('feed-status').className='feed-bad';$('feed-status').textContent=`Connection failed: ${err.message} ${target==='Popdex'?'Use Start Pairdesk.command to run the local data relay.':''}`;}}finally{feedBusy.delete(target);if(venue===target){$('refresh-feed').disabled=false;$('refresh-feed').textContent='Refresh prices';}}}
$('refresh-feed').onclick=refreshFeed;$('tradfi-only').onchange=renderFeed;$('market-search').oninput=renderFeed;$('live-a').onchange=renderLivePair;$('live-b').onchange=renderLivePair;
$('load-history').onclick=async()=>{const target=venue,a=$('live-a').value,b=$('live-b').value;if(historyBusy||!a||a===b||target==='Variational')return;historyBusy=true;renderLivePair();$('history-status').textContent='Loading both legs and matching completed bars by timestamp…';try{const [ha,hb]=await Promise.all([MarketFeeds.history(target,a),MarketFeeds.history(target,b)]),rows=MarketFeeds.align(ha,hb);if(rows.length<100)throw Error(`Only ${rows.length} common completed bars. At least 100 are required.`);const gaps=rows.filter((r,i)=>i&&r.t-rows[i-1].t!==300000).length;const item={a,b,rows,venue:target,kind:target==='Arcus'?'Arcus oracle-price history':'Popdex market-candle history',sector:'Connected · '+(target==='Arcus'?'oracle prices':'market candles'),demo:false,connected:true,fetched:Date.now()};const existing=imported.findIndex(p=>p.connected&&p.venue===target&&p.a===a&&p.b===b);if(existing>=0)imported[existing]=item;else imported.push(item);if(venue===target){selected=list().indexOf(item);resetResult();render();show('scanner');}const note=`Loaded ${rows.length} matched bars for ${a}/${b}; ${gaps} gaps. Latest bar opened ${date(rows.at(-1).t)} UTC. Reload from Exchange data for an update.`;$('history-status').textContent=note;toast(`Loaded ${rows.length} real ${target} bars. Scanner and backtester are ready.`);}catch(err){$('history-status').textContent='Could not load history: '+err.message;}finally{historyBusy=false;renderLivePair();}};
setInterval(()=>{if(page==='live'&&!document.hidden){if($('auto-feed').checked)refreshFeed();else if(feedCache[venue])renderFeed();}},60000);
document.querySelectorAll('[data-venue]').forEach(button=>button.addEventListener('click',()=>{$('history-status').textContent='Historical data loads only when requested. Snapshot refresh does not refresh scanner history.';if(page==='live')renderFeed();}));
// The automatic scanner owns the initial market refresh.

